async function bgmAttach(sid,btn){
  var knownT=(btn&&btn.parentNode&&btn.parentNode.getAttribute)?String(btn.parentNode.getAttribute('data-t')||''):'';
  if(knownT){ var _d=shows.filter(function(x){ return normTxt(x.title)===normTxt(knownT); })[0]; if(_d){ toast('已在片单：《'+_d.title+'》（未重复添加）'); return; } }
  if(shows.some(function(x){ return String(x.bgmId||'')===String(sid); })){ toast('已在片单里了'); return; }
  btn.disabled=true; btn.textContent='拉取中…';
  document.getElementById('srMsg').textContent='正在拉取剧集列表…';
  try{
    var pr=await bgmPullEpisodeList(sid), det=pr.det, ded=pr.ded;
    var coverUrl=(det.images&&det.images.common)||'';
    try{ coverUrl=await cacheCover(coverUrl,true); }catch(e2){}
    addShow({ sid:sid, title:det.name_cn||det.name||('bgm'+sid), nameJp:det.name||'', cover:coverUrl, year:det.date?String(det.date).slice(0,4):'', total:ded.length, eps:ded, statuses:{}, status:'watching', addedAt:Date.now(), updAt:Date.now(), source:'Bangumi #'+sid, bgmId:String(sid) });
  }catch(e){
    btn.disabled=false; btn.textContent='添加';
    document.getElementById('srMsg').textContent='拉取失败：'+e.message+'——可稍后重试，或浏览本地库/手动添加（无需网络）';
  }
}

