async function bgmPullEpisodeList(sid){ /* v2.4.1 提取自 bgmAttach：拉取并规整剧集列表（搜索添加/关联补齐共用） */
  var det=await _bget(BAPI+'/subjects/'+sid);
  var eps=[], off=0;
  while(true){
    var r=await _bget(BAPI+'/episodes?subject_id='+sid+'&limit=100&offset='+off);
    (r.data||[]).forEach(function(e){ eps.push(e); });
    if((r.data||[]).length<100||off>=3000) break;
    off+=100;
  }
  var list=eps.filter(function(e){ return e.type===0||e.type===1; }).map(function(e){
    return {s:(e.sort!==undefined&&e.sort!==''&&+e.sort>0)?+e.sort:0, t:(e.name_cn||e.name||''), ref:null, dur:24, bid:e.id}; /* 来源标注交给判定器/AFG，不默认 canon */
  }).filter(function(e){ return e.s>0; });
  /* SP/特别篇 sort 异常大的排到正篇后顺延（避免显示"第 10001 集"） */
  var normal=list.filter(function(e){ return e.s<=5000; });
  var specials=list.filter(function(e){ return e.s>5000; });
  var maxN=normal.length?Math.max.apply(null,normal.map(function(e){ return e.s; })):0;
  specials.sort(function(a,b){ return a.s-b.s; }).forEach(function(e,i){ e.s=maxN+i+1; e.type='semi'; });
  list=normal.concat(specials);
  list.sort(function(a,b){ return a.s-b.s; });
  var seen={}, ded=[];
  list.forEach(function(e){ if(seen[e.s]){ e.s=Math.max.apply(null,Object.keys(seen).map(Number).concat([maxN]))+1; } seen[e.s]=1; ded.push(e); });
  if(!ded.length) throw new Error('该条目没有可用剧集');
  return {det:det, ded:ded};
}
